select * from (select * from (select A.*, rownum rn from ( SELECT , p.permission_type permissionType FROM xxl_job_info t left join xxl_job_permission p on t.id = p.job_id
AND p.user_id = #{userId}
AND (t.TENANT_ID = '1000' OR t.TENANT_ID IS NULL OR t.TENANT_ID = #{tenantId})
AND t.job_group = #{jobGroup}
AND t.trigger_status = #{triggerStatus}
AND t.id = #{jobId}
AND t.job_desc like CONCAT(CONCAT('%', #{jobDesc}), '%')
AND t.executor_handler like CONCAT(CONCAT('%', #{executorHandler}), '%')
AND t.author like CONCAT(CONCAT('%', #{author}), '%')
ORDER BY t.job_desc ORDER BY t.schedule_type ORDER BY t.schedule_conf ORDER BY t.glue_type ORDER BY t.trigger_status ORDER BY t.id
ASC DESC
) A) where rn > #{offset}) B where rn < #{offset}+ #{pagesize}

